import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十卦 离 离为火 离上离下","description":"周易 - 第三十卦 离 离为火 离上离下","frontmatter":{"title":"第三十卦 离 离为火 离上离下","description":"周易 - 第三十卦 离 离为火 离上离下"},"headers":[],"relativePath":"zh/classics/zhouyi/031.md","filePath":"zh/classics/zhouyi/031.md"}'),l={name:"zh/classics/zhouyi/031.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="离" tabindex="-1">离 <a class="header-anchor" href="#离" aria-label="Permalink to “离”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利贞，亨。畜牝牛，吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>离，丽也；日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正，故亨；是以畜牝牛吉也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>明两作离，大人以继明照于四方。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>履错然，敬之无咎。象曰：履错之敬， 以辟咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>黄离，元吉。象曰：黄离元吉，得中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>日昃之离，不鼓缶而歌，则大耋之嗟，凶。象曰：日昃之离，何可久也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>突如其来如，焚如，死如，弃如。象曰：突如其来如，无所容也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>出涕沱若，戚嗟若，吉。象曰：六五之吉，离王公也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>王用出征，有嘉折首，获其匪丑，无咎。象曰：王用出征，以正邦也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
